cat << 'EOF' > src/transport/ws/listSessions.test.ts
import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';

describe('list_sessions in messageHandler', () => {
  it('calls sessionStore.listFor and answers session_list with ISO dates', async () => {
    const orchestrator = {} as ChatOrchestrator;
    const store = {
      listFor: jest.fn().mockResolvedValue([
        {
          sessionId: 's1',
          createdAt: new Date('2026-01-01T00:00:00.000Z'),
          updatedAt: new Date('2026-01-01T00:02:00.000Z'),
          entryCount: 2,
        },
      ]),
    } as unknown as SessionStore;
    const ws = { send: jest.fn() } as unknown as WebSocket;
    const session = { userId: 'u1' } as ChatSession;

    const handler = createMessageHandler(orchestrator, store);
    await handler(ws, session, { type: 'list_sessions', limit: 10 });

    expect(store.listFor).toHaveBeenCalledWith('u1', { limit: 10, before: undefined });
    expect(ws.send).toHaveBeenCalledWith(JSON.stringify({
      type: 'session_list',
      sessions: [
        {
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:02:00.000Z',
          entryCount: 2,
        }
      ]
    }));
  });
});
EOF
npm run test -- src/transport/ws/listSessions.test.ts
